import{_ as a,o as t,c as l,ag as s}from"./chunks/framework.DaCm-iTo.js";const m=JSON.parse('{"title":"PlaceholderAPI","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/level/placeholders.md","filePath":"en/modules/level/placeholders.md","lastUpdated":null}'),n={name:"en/modules/level/placeholders.md"};function o(i,e,r,d,p,c){return t(),l("div",null,[...e[0]||(e[0]=[s(`<h1 id="placeholderapi" tabindex="-1">PlaceholderAPI <a class="header-anchor" href="#placeholderapi" aria-label="Permalink to &quot;PlaceholderAPI&quot;">​</a></h1><p>When PlaceholderAPI is installed, EmakiLevel registers the <code>emakilevel</code> expansion. These placeholders can be used in scoreboards, menus, chat formats, BossBars, ActionBars, and other plugins that support PlaceholderAPI.</p><p>If PlaceholderAPI is not installed, EmakiLevel still runs normally; only external <code>%emakilevel_*%</code> placeholders are not registered.</p><h2 id="player-level-placeholders" tabindex="-1">Player level placeholders <a class="header-anchor" href="#player-level-placeholders" aria-label="Permalink to &quot;Player level placeholders&quot;">​</a></h2><p>Player placeholders require a player context.</p><table tabindex="0"><thead><tr><th>Placeholder</th><th>Returns</th></tr></thead><tbody><tr><td><code>%emakilevel_level_&lt;type&gt;%</code></td><td>Current level.</td></tr><tr><td><code>%emakilevel_exp_&lt;type&gt;%</code></td><td>Current-level exp.</td></tr><tr><td><code>%emakilevel_total_exp_&lt;type&gt;%</code></td><td>Total exp.</td></tr><tr><td><code>%emakilevel_totalexp_&lt;type&gt;%</code></td><td>Total exp, no-underscore alias.</td></tr><tr><td><code>%emakilevel_total_&lt;type&gt;%</code></td><td>Total exp, short alias.</td></tr><tr><td><code>%emakilevel_required_exp_&lt;type&gt;%</code></td><td>Required exp for the next level.</td></tr><tr><td><code>%emakilevel_requiredexp_&lt;type&gt;%</code></td><td>Required exp, no-underscore alias.</td></tr><tr><td><code>%emakilevel_required_&lt;type&gt;%</code></td><td>Required exp, short alias.</td></tr><tr><td><code>%emakilevel_progress_&lt;type&gt;%</code></td><td>Progress from 0 to 1.</td></tr><tr><td><code>%emakilevel_progress_percent_&lt;type&gt;%</code></td><td>Progress from 0 to 100.</td></tr></tbody></table><p>Examples:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>%emakilevel_level_main%</span></span>
<span class="line"><span>%emakilevel_exp_main%</span></span>
<span class="line"><span>%emakilevel_required_exp_main%</span></span>
<span class="line"><span>%emakilevel_progress_percent_main%</span></span>
<span class="line"><span>%emakilevel_level_combat%</span></span>
<span class="line"><span>%emakilevel_total_exp_mining%</span></span></code></pre></div><p>If <code>&lt;type&gt;</code> does not exist or player data cannot be loaded, the placeholder returns an empty string.</p><h2 id="leaderboard-placeholders" tabindex="-1">Leaderboard placeholders <a class="header-anchor" href="#leaderboard-placeholders" aria-label="Permalink to &quot;Leaderboard placeholders&quot;">​</a></h2><p>Leaderboards use the plugin&#39;s currently cached player level data. Online players and already-loaded data can appear in the cache; this is not a full offline database scan.</p><table tabindex="0"><thead><tr><th>Placeholder</th><th>Returns</th></tr></thead><tbody><tr><td><code>%emakilevel_top_&lt;type&gt;_&lt;rank&gt;_name%</code></td><td>Player name at rank.</td></tr><tr><td><code>%emakilevel_top_&lt;type&gt;_&lt;rank&gt;_level%</code></td><td>Level at rank.</td></tr><tr><td><code>%emakilevel_top_&lt;type&gt;_&lt;rank&gt;_total_exp%</code></td><td>Total exp at rank.</td></tr><tr><td><code>%emakilevel_top_&lt;type&gt;_&lt;rank&gt;_totalexp%</code></td><td>Total exp, no-underscore alias.</td></tr><tr><td><code>%emakilevel_top_&lt;type&gt;_&lt;rank&gt;_total%</code></td><td>Total exp, short alias.</td></tr></tbody></table><p>Examples:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>%emakilevel_top_main_1_name%</span></span>
<span class="line"><span>%emakilevel_top_main_1_level%</span></span>
<span class="line"><span>%emakilevel_top_main_1_total_exp%</span></span>
<span class="line"><span>%emakilevel_top_combat_3_name%</span></span></code></pre></div><blockquote><p>Leaderboard placeholders are parsed as <code>top_&lt;type&gt;_&lt;rank&gt;_&lt;field&gt;</code>. Default type IDs do not contain underscores. If you create custom type IDs with underscores, player placeholders can still parse them, but leaderboard placeholders should use type IDs without underscores to avoid ambiguity.</p></blockquote><h2 id="number-formatting" tabindex="-1">Number formatting <a class="header-anchor" href="#number-formatting" aria-label="Permalink to &quot;Number formatting&quot;">​</a></h2><ul><li>Integer values are displayed as integers, for example <code>120</code>.</li><li>Decimal values keep two decimal places, for example <code>12.50</code>.</li><li><code>progress</code> is a value from 0 to 1.</li><li><code>progress_percent</code> is a value from 0 to 100 and does not include the <code>%</code> symbol.</li></ul><p>Scoreboard example:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Main Level: Lv.%emakilevel_level_main%</span></span>
<span class="line"><span>Main Exp: %emakilevel_exp_main%/%emakilevel_required_exp_main%</span></span>
<span class="line"><span>Progress: %emakilevel_progress_percent_main%%</span></span>
<span class="line"><span>Combat Level: Lv.%emakilevel_level_combat%</span></span>
<span class="line"><span>Top #1: %emakilevel_top_main_1_name% Lv.%emakilevel_top_main_1_level%</span></span></code></pre></div><p>In <code>%emakilevel_progress_percent_main%%</code>, <code>%emakilevel_progress_percent_main%</code> is the placeholder and the last <code>%</code> is literal text.</p><h2 id="common-usage" tabindex="-1">Common usage <a class="header-anchor" href="#common-usage" aria-label="Permalink to &quot;Common usage&quot;">​</a></h2><p>Menu lore:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">lore</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;gray&gt;Main Level: &lt;yellow&gt;Lv.%emakilevel_level_main%&lt;/yellow&gt;&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;gray&gt;Exp: &lt;green&gt;%emakilevel_exp_main%&lt;/green&gt;/&lt;green&gt;%emakilevel_required_exp_main%&lt;/green&gt;&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;gray&gt;Progress: &lt;aqua&gt;%emakilevel_progress_percent_main%%&lt;/aqua&gt;&quot;</span></span></code></pre></div><p>Condition plugins:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>%emakilevel_level_combat% &gt;= 20</span></span>
<span class="line"><span>%emakilevel_progress_percent_mining% &gt;= 75</span></span></code></pre></div><p>Chat display:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Lv.%emakilevel_level_main%] %player_name%: %message%</span></span></code></pre></div><h2 id="difference-from-internal-action-variables" tabindex="-1">Difference from internal action variables <a class="header-anchor" href="#difference-from-internal-action-variables" aria-label="Permalink to &quot;Difference from internal action variables&quot;">​</a></h2><p>PlaceholderAPI placeholders are external <code>%emakilevel_*%</code> variables. EmakiLevel&#39;s <code>types/&lt;type&gt;.yml &gt; upgrade.actions.*</code> provides internal action variables such as <code>%level%</code>, <code>%new_level%</code>, <code>%amount%</code>, and <code>%failure_reason%</code>. Both use <code>%key%</code> syntax, but their scopes are different.</p><p>See <a href="./configuration.html#upgrade-action-variables">Configuration</a> for action variables.</p>`,30)])])}const _=a(n,[["render",o]]);export{m as __pageData,_ as default};
